@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_create_user(api_client, scenario_case, config_test_data):
    """
    Test creating a user with various scenarios based on the provided test data.

    :param api_client: Fixture providing an API client instance.
    :param scenario_case: Test case data from the JSON file.
    :param config_test_data: Default test data from config.
    """
    # Prepare request data
    request_data = {
        "id": scenario_case.get("id"),
        "username": scenario_case.get("username"),
        "firstName": scenario_case.get("firstName"),
        "lastName": scenario_case.get("lastName"),
        "email": scenario_case.get("email"),
        "password": scenario_case.get("password"),
        "phone": scenario_case.get("phone"),
        "userStatus": scenario_case.get("userStatus")
    }
    
    # Validate request schema
    swagger_validator.validate_json(request_data, "User")

    # Make API request
    response = api_client.post("/user", data=request_data)

    # Validate response schema
